def is_perfect_number(n):
    if n < 1:
        return False
    if n == 1:
        return False
    divisors = {1}
    i = 2
    while i * i <= n:
        if n % i == 0:
            divisors.add(i)
            other = n // i
            if other != n:
                divisors.add(other)
        i += 1
    return sum(divisors) == n

