def reorder_by_priority_with_fallback_alpha(items, priority):
    priority_index = {}
    for i, p in enumerate(priority):
        priority_index[p] = i
    front = [x for x in items if x in priority_index]
    front.sort(key=lambda x: priority_index[x])
    back = [x for x in items if x not in priority_index]
    back.sort()
    return front + back

