def flatten_and_count(nested):
    counts = {}
    stack = list(nested)
    while stack:
        item = stack.pop(0)
        if isinstance(item, list):
            stack = list(item) + stack
        else:
            counts[item] = counts.get(item, 0) + 1
    return counts

