def is_valid_utc_offset(s):
    if not s or s[0] not in '+-':
        return False
    sign = -1 if s[0] == '-' else 1
    parts = s[1:].split(':')
    if len(parts) != 2:
        return False
    hh, mm = parts
    if not (len(hh) == 2 and len(mm) == 2 and hh.isdigit() and mm.isdigit()):
        return False
    minutes = sign * (int(hh) * 60 + int(mm))
    return int(mm) <= 59 and -720 <= minutes <= 840

